import json, csv, os, sys, hashlib

MATRIX = ["buffer", "serum", "plasma", "lysate", "saliva", "urine", "media"]


def load(prefix, d="/app/data"):
    p = lambda n: os.path.join(d, prefix + n)
    rd = lambda n: list(csv.DictReader(open(p(n))))
    man = json.load(open(p("manifest.json")))
    ins = {r["instrument"]: r for r in rd("instruments.csv")}
    pan = {r["panel"]: r for r in rd("panels.csv")}
    ops = {r["operator"]: r for r in rd("operators.csv")}
    plt = {r["plate"]: r for r in rd("plates.csv")}
    reads = [json.loads(l) for l in open(p("reads.jsonl")) if l.strip()]
    return man, ins, pan, ops, plt, reads


def clamp(x):
    return x if x > 0 else 0


TOL = {"technician": 25, "scientist": 40, "trainee": 12, "service": 0}


def matrix_adj(m, f):
    if m == "buffer":
        return f
    if m == "serum":
        return f - 4
    if m == "plasma":
        return f * 3 // 4
    if m == "lysate":
        return f + 6
    if m == "saliva":
        return f // 2
    if m == "urine":
        return f // 5 * 5
    if m == "media":
        return f * 5 // 4
    raise KeyError(m)


def panel_adj(fam, f):
    if fam == "elisa":
        return f
    if fam == "pcr":
        return f * 9 // 10
    if fam == "turbidity":
        return f + 12
    if fam == "fluor":
        return f * 7 // 5
    raise KeyError(fam)


def grade(v):
    if v >= 240:
        return "high"
    if v >= 120:
        return "mid"
    if v >= 40:
        return "low"
    return "trace"


COUNTED = {"ok", "review"}


def run(man, ins, pan, ops, plt, reads):
    state = {k: {"blank": int(ins[v["instrument"]]["baseline"]), "drift": 0, "strikes": 0}
             for k, v in plt.items()}
    order = sorted(reads, key=lambda r: r["seq"])
    readings = []
    for r in order:
        p = plt[r["plate"]]
        st = state[r["plate"]]
        f = clamp(r["raw"] - st["blank"])
        f = clamp(f * 1000 // r["exposure"])
        f = clamp(matrix_adj(p["matrix"], f))
        f = clamp(panel_adj(pan[p["panel"]]["family"], f))
        db = st["drift"]
        v = clamp(f - db)
        g = grade(v)
        act = r["action"]
        if act in ("blank", "recal"):
            status = "setup"
        elif act == "mask":
            status = "masked"
        elif g == "trace":
            status = "reject"
        elif db > TOL[ops[r["operator"]]["role"]]:
            status = "review"
        else:
            status = "ok"
        readings.append({"action": act, "drift_before": db, "grade": g,
                         "operator": r["operator"], "plate": r["plate"], "seq": r["seq"],
                         "status": status, "value": v, "well": r["well"]})
        if act == "blank":
            st["blank"] = r["raw"]
        elif act == "recal":
            st["drift"] = 0
        elif act == "measure":
            c = r["exposure"] // 50
            if p["tier"] == "3":
                c *= 2
            st["drift"] = min(90, st["drift"] + c)
        if status == "reject":
            st["strikes"] += 1
    rows = []
    for name in sorted(plt):
        mine = [x for x in readings if x["plate"] == name]
        st = state[name]
        counted = [x for x in mine if x["status"] in COUNTED]
        peak = 0
        top = None
        for x in counted:
            if x["value"] >= peak and (top is None or x["value"] >= peak):
                if x["value"] >= peak:
                    peak = x["value"]
                    top = x["well"]
        if not counted:
            peak, top = 0, None
        grades = {k: 0 for k in ("high", "low", "mid", "trace")}
        for x in mine:
            grades[x["grade"]] += 1
        rej = st["strikes"]
        if rej >= 3:
            disp = "quarantine"
        elif st["drift"] > 30:
            disp = "hold"
        else:
            disp = "release"
        rows.append({"blank_end": st["blank"], "disposition": disp, "drift_end": st["drift"],
                     "grades": grades, "measured": sum(1 for x in mine if x["action"] == "measure"),
                     "peak": peak, "plate": name, "reads": len(mine), "rejects": rej,
                     "reviewed": sum(1 for x in mine if x["status"] == "review"),
                     "top_well": top, "value_total": sum(x["value"] for x in counted)})
    bg = {k: 0 for k in ("high", "low", "mid", "trace")}
    bs = {k: 0 for k in ("masked", "ok", "reject", "review", "setup")}
    for x in readings:
        bg[x["grade"]] += 1
        bs[x["status"]] += 1
    tp = None
    best = -1
    for row in rows:
        if row["value_total"] > best:
            best = row["value_total"]
            tp = row["plate"]
    if not rows:
        tp = None
    bench = {"by_grade": bg, "by_status": bs, "plates": len(rows),
             "quarantined": sorted(r["plate"] for r in rows if r["disposition"] == "quarantine"),
             "reads": len(readings), "top_plate": tp,
             "value_total": sum(r["value_total"] for r in rows)}
    return readings, {"plates": rows}, bench


def texts(readings, plates, bench):
    rl = "".join(json.dumps(r, sort_keys=True, separators=(",", ":")) + "\n" for r in readings)
    pl = json.dumps(plates, sort_keys=True, indent=2) + "\n"
    bl = json.dumps(bench, sort_keys=True, indent=2) + "\n"
    return rl, pl, bl


def digests(readings, plates, bench):
    rl, pl, bl = texts(readings, plates, bench)
    pd = {}
    for row in plates["plates"]:
        t = "".join(json.dumps(r, sort_keys=True, separators=(",", ":")) + "\n"
                    for r in readings if r["plate"] == row["plate"])
        t += json.dumps(row, sort_keys=True, indent=2) + "\n"
        pd[row["plate"]] = hashlib.sha256(t.encode()).hexdigest()
    return pd, hashlib.sha256((rl + pl + bl).encode()).hexdigest()


if __name__ == "__main__":
    for pref in ("example_a_", "example_b_"):
        man, ins, pan, ops, plt, reads = load(pref)
        readings, plates, bench = run(man, ins, pan, ops, plt, reads)
        pd, rd = digests(readings, plates, bench)
        bad = [k for k in man["plate_digests"] if man["plate_digests"][k] != pd.get(k)]
        print(pref, "plates bad:", bad, "run:", rd == man["run_digest"])
        # also compare shipped output text
        rl, pl, bl = texts(readings, plates, bench)
        print("  readings match:", rl == open("/app/data/" + pref + "out_readings.jsonl").read(),
              "plates match:", pl == open("/app/data/" + pref + "out_plates.json").read(),
              "bench match:", bl == open("/app/data/" + pref + "out_bench.json").read())

