"""Parametrized engine: knobs default to the mode-0 chain."""
import json, csv, os, hashlib

MATRICES = ["buffer", "serum", "plasma", "lysate", "saliva", "urine", "media"]
FAMILIES = ["elisa", "pcr", "turbidity", "fluor"]
ROLES = ["technician", "scientist", "trainee", "service"]
GR = ("high", "low", "mid", "trace")

MADJ = {
    "buffer": ("id", 0),
    "serum": ("add", -4),
    "plasma": ("mul", (3, 4)),
    "lysate": ("add", 6),
    "saliva": ("mul", (1, 2)),
    "urine": ("snap", 5),
    "media": ("mul", (5, 4)),
}
PADJ = {
    "elisa": ("id", 0),
    "pcr": ("mul", (9, 10)),
    "turbidity": ("add", 12),
    "fluor": ("mul", (7, 5)),
}


def apply_adj(spec, f):
    kind, arg = spec
    if kind == "id":
        return f
    if kind == "add":
        return f + arg
    if kind == "mul":
        return f * arg[0] // arg[1]
    if kind == "snap":
        return f // arg * arg
    raise ValueError(kind)


DEFAULT = {
    "base_src": "blank",          # blank | baseline
    "gain": 1000,
    "div": "floor",               # floor | ceil | round
    "matrix_key": 0,              # 0 | +1 | -1 | 'skip'
    "panel_key": 0,
    "drift_op": "sub",            # sub | add | skip
    "bands": (240, 120, 40),
    "band_cmp": "ge",             # ge | gt
    "ladder": "std",              # std | mask_first | reject_low
    "tol": {"technician": 25, "scientist": 40, "trainee": 12, "service": 0},
    "tol_cmp": "gt",              # gt | ge
    "charge_div": 50,
    "charge_src": "exposure",     # exposure | raw
    "tier_mult_on": "3",          # which tier doubles: '1','2','3',None,'all'
    "tier_mult": 2,
    "ceiling": 90,
    "charge_actions": ("measure",),
    "blank_update": "raw",        # raw | value | none
    "recal": "drift",             # drift | drift_blank | none
    "strike_on": ("reject",),
    "counted": ("ok", "review"),
    "peak_src": "counted",        # counted | all
    "well_tie": "last",           # last | first
    "quar": 3,
    "hold": 30,
    "walk": "all",                # all | drop_last
    "order": "seq",               # seq | plate | desc
    "bench_total": "plates",
    "plate_tie": "first",
}


def clamp(x):
    return x if x > 0 else 0


def divide(f, exp, gain, mode):
    n = f * gain
    if mode == "floor":
        return n // exp
    if mode == "ceil":
        return -(-n // exp)
    if mode == "round":
        return (n + exp // 2) // exp
    raise ValueError(mode)


def shift_key(lst, key, sh):
    if sh == "skip":
        return None
    i = lst.index(key)
    return lst[(i + sh) % len(lst)]


def grade_of(v, bands, cmp):
    h, m, l = bands
    if cmp == "ge":
        if v >= h:
            return "high"
        if v >= m:
            return "mid"
        if v >= l:
            return "low"
        return "trace"
    else:
        if v > h:
            return "high"
        if v > m:
            return "mid"
        if v > l:
            return "low"
        return "trace"


def resolve(plate_row, pan, ops, ins, reads, K):
    """reads: list for this plate in resolution order. Returns (readings, state)."""
    mat = plate_row["matrix"]
    fam = pan[plate_row["panel"]]["family"]
    repl = int(pan[plate_row["panel"]]["replicates"])
    base = int(ins[plate_row["instrument"]]["baseline"])
    tier = plate_row["tier"]
    st = {"blank": base, "drift": 0, "strikes": 0}
    mk = shift_key(MATRICES, mat, K["matrix_key"]) if K["matrix_key"] != 0 else mat
    pk = shift_key(FAMILIES, fam, K["panel_key"]) if K["panel_key"] != 0 else fam
    out = []
    for r in reads:
        src = st["blank"] if K["base_src"] == "blank" else base
        f = clamp(r["raw"] - src)
        f = clamp(divide(f, r["exposure"], K["gain"], K["div"]))
        if mk is not None:
            f = clamp(apply_adj(MADJ[mk], f))
        if pk is not None:
            f = clamp(apply_adj(PADJ[pk], f))
        db = st["drift"]
        if K["drift_op"] == "sub":
            v = clamp(f - db)
        elif K["drift_op"] == "add":
            v = clamp(f + db)
        else:
            v = clamp(f)
        g = grade_of(v, K["bands"], K["band_cmp"])
        act = r["action"]
        role = ops[r["operator"]]["role"]
        tol = K["tol"][role]
        over = db > tol if K["tol_cmp"] == "gt" else db >= tol
        if K["ladder"] == "std":
            if act in ("blank", "recal"):
                status = "setup"
            elif act == "mask":
                status = "masked"
            elif g == "trace":
                status = "reject"
            elif over:
                status = "review"
            else:
                status = "ok"
        elif K["ladder"] == "mask_first":
            if act == "mask":
                status = "masked"
            elif act in ("blank", "recal"):
                status = "setup"
            elif g == "trace":
                status = "reject"
            elif over:
                status = "review"
            else:
                status = "ok"
        elif K["ladder"] == "review_first":
            if act in ("blank", "recal"):
                status = "setup"
            elif act == "mask":
                status = "masked"
            elif over:
                status = "review"
            elif g == "trace":
                status = "reject"
            else:
                status = "ok"
        elif K["ladder"] == "reject_low":
            if act in ("blank", "recal"):
                status = "setup"
            elif act == "mask":
                status = "masked"
            elif g in ("trace", "low"):
                status = "reject"
            elif over:
                status = "review"
            else:
                status = "ok"
        elif K["ladder"] == "all_graded":
            # setup/mask actions still graded but statuses from value only
            if g == "trace":
                status = "reject"
            elif over:
                status = "review"
            else:
                status = "ok"
        else:
            raise ValueError(K["ladder"])
        out.append({"action": act, "drift_before": db, "grade": g, "operator": r["operator"],
                    "plate": r["plate"], "seq": r["seq"], "status": status, "value": v,
                    "well": r["well"]})
        if act == "blank":
            if K["blank_update"] == "raw":
                st["blank"] = r["raw"]
            elif K["blank_update"] == "value":
                st["blank"] = v
        elif act == "recal":
            if K["recal"] in ("drift", "drift_blank"):
                st["drift"] = 0
            if K["recal"] == "drift_blank":
                st["blank"] = base
        if act in K["charge_actions"]:
            srcv = r["exposure"] if K["charge_src"] == "exposure" else r["raw"]
            c = srcv // K["charge_div"]
            if K["tier_mult_on"] == "all" or tier == K["tier_mult_on"]:
                c *= K["tier_mult"]
            nd = st["drift"] + c
            if K["ceiling"] is not None and nd > K["ceiling"]:
                nd = K["ceiling"]
            st["drift"] = nd
        if status in K["strike_on"]:
            st["strikes"] += 1
    return out, st


def plate_row(name, mine, st, K):
    counted = [x for x in mine if x["status"] in K["counted"]]
    pool = counted if K["peak_src"] == "counted" else mine
    peak = 0
    top = None
    for x in pool:
        if top is None:
            peak, top = x["value"], x["well"]
        elif K["well_tie"] == "last":
            if x["value"] >= peak:
                peak, top = x["value"], x["well"]
        else:
            if x["value"] > peak:
                peak, top = x["value"], x["well"]
    if not pool:
        peak, top = 0, None
    grades = {k: 0 for k in GR}
    for x in mine:
        grades[x["grade"]] += 1
    rej = st["strikes"]
    if rej >= K["quar"]:
        disp = "quarantine"
    elif st["drift"] > K["hold"]:
        disp = "hold"
    else:
        disp = "release"
    return {"blank_end": st["blank"], "disposition": disp, "drift_end": st["drift"],
            "grades": grades, "measured": sum(1 for x in mine if x["action"] == "measure"),
            "peak": peak, "plate": name, "reads": len(mine), "rejects": rej,
            "reviewed": sum(1 for x in mine if x["status"] == "review"),
            "top_well": top, "value_total": sum(x["value"] for x in counted)}


def line(d):
    return json.dumps(d, sort_keys=True, separators=(",", ":")) + "\n"


def plate_digest(name, mine, row):
    t = "".join(line(x) for x in mine) + json.dumps(row, sort_keys=True, indent=2) + "\n"
    return hashlib.sha256(t.encode()).hexdigest()


def load(prefix, d="/app/data"):
    p = lambda n: os.path.join(d, prefix + n)
    rd = lambda n: list(csv.DictReader(open(p(n))))
    man = json.load(open(p("manifest.json")))
    ins = {r["instrument"]: r for r in rd("instruments.csv")}
    pan = {r["panel"]: r for r in rd("panels.csv")}
    ops = {r["operator"]: r for r in rd("operators.csv")}
    plt = {r["plate"]: r for r in rd("plates.csv")}
    reads = [json.loads(l) for l in open(p("reads.jsonl")) if l.strip()]
    return man, ins, pan, ops, plt, reads


def plate_reads(reads, name, K):
    order = sorted(reads, key=lambda r: r["seq"])
    if K["walk"] == "drop_last":
        order = order[:-1]
    return [r for r in order if r["plate"] == name]


def one_plate(name, K, data):
    man, ins, pan, ops, plt, reads = data
    mine = plate_reads(reads, name, K)
    out, st = resolve(plt[name], pan, ops, ins, mine, K)
    row = plate_row(name, out, st, K)
    return plate_digest(name, out, row), out, row

"""Search PLT-29 (5 mask reads) output space against its digest."""
import json, hashlib, itertools

man = json.load(open('/app/data/manifest.json'))
target = man['plate_digests']['PLT-29']
reads = [r for r in map(json.loads, open('/app/data/reads.jsonl')) if r['plate'] == 'PLT-29']
reads.sort(key=lambda r: r['seq'])
BASE = 100
GR = ("high", "low", "mid", "trace")

GAINS = [1, 2, 4, 5, 8, 10, 16, 20, 25, 32, 40, 50, 64, 100, 125, 128, 200, 250, 256, 400, 500,
         512, 625, 750, 800, 900, 1000, 1024, 1100, 1200, 1250, 1500, 1600, 2000, 2048, 2500,
         3000, 4000, 4096, 5000, 10000, 100000]
MADJ = [("id", 0), ("add", -4), ("mul", (3, 4)), ("add", 6), ("mul", (1, 2)), ("snap", 5), ("mul", (5, 4))]
PADJ = [("id", 0), ("mul", (9, 10)), ("add", 12), ("mul", (7, 5))]


def apply_adj(spec, f):
    k, a = spec
    if k == "id":
        return f
    if k == "add":
        return f + a
    if k == "mul":
        return f * a[0] // a[1]
    if k == "snap":
        return f // a * a
    raise ValueError


def clamp(x):
    return x if x > 0 else 0


def div(n, e, mode):
    if mode == "floor":
        return n // e
    if mode == "ceil":
        return -(-n // e)
    return (n + e // 2) // e


def line(d):
    return json.dumps(d, sort_keys=True, separators=(",", ":")) + "\n"


# ---- build value scenarios
scen = {}
for gain in GAINS:
    for dm in ("floor", "ceil", "round"):
        for mi, ma in enumerate(MADJ):
            for pi, pa in enumerate(PADJ):
                for chargemask in (0, 1):
                    for cdiv in (50,):
                        vals = []
                        dbs = []
                        drift = 0
                        for r in reads:
                            f = clamp(r['raw'] - BASE)
                            f = clamp(div(f * gain, r['exposure'], dm))
                            f = clamp(apply_adj(ma, f))
                            f = clamp(apply_adj(pa, f))
                            dbs.append(drift)
                            vals.append(clamp(f - drift))
                            if chargemask:
                                drift = min(90, drift + r['exposure'] // cdiv)
                        key = (tuple(vals), tuple(dbs), drift)
                        scen.setdefault(key, (gain, dm, mi, pi, chargemask))
print("value scenarios:", len(scen))

# ---- grade labelings: monotone decreasing bands
def labelings(vals):
    cand = sorted({0, 1} | {v for v in vals} | {v + 1 for v in vals} | {max(vals) + 2})
    seen = {}
    for h, m, l in itertools.combinations_with_replacement(cand[::-1], 3):
        if not (h >= m >= l):
            continue
        lab = []
        for v in vals:
            lab.append("high" if v >= h else "mid" if v >= m else "low" if v >= l else "trace")
        seen.setdefault(tuple(lab), (h, m, l))
    return seen


hits = []
for key, params in scen.items():
    vals, dbs, drift_end = key
    labs = labelings(list(vals))
    for lab, bands in labs.items():
        for statmode in ("masked", "graded"):
            if statmode == "masked":
                stats = ["masked"] * len(vals)
            else:
                stats = ["reject" if g == "trace" else "ok" for g in lab]
            txt = "".join(line({"action": "mask", "drift_before": dbs[i], "grade": lab[i],
                                "operator": reads[i]['operator'], "plate": "PLT-29",
                                "seq": reads[i]['seq'], "status": stats[i], "value": vals[i],
                                "well": reads[i]['well']}) for i in range(len(vals)))
            grades = {k: 0 for k in GR}
            for g in lab:
                grades[g] += 1
            for pool in ("none", "all"):
                for tie in ("last", "first"):
                    if pool == "none":
                        peak, top, vt = 0, None, 0
                    else:
                        peak, top = -1, None
                        for i, v in enumerate(vals):
                            if v > peak or (tie == "last" and v >= peak):
                                peak, top = v, reads[i]['well']
                        vt = sum(vals)
                    for vtmode in (0, 1):
                        for be in (100, 130, 300):
                            for disp in ("release", "hold", "quarantine"):
                                rej = sum(1 for s in stats if s == "reject")
                                for rejv in {0, rej}:
                                    row = {"blank_end": be, "disposition": disp,
                                           "drift_end": drift_end, "grades": grades,
                                           "measured": 0, "peak": peak, "plate": "PLT-29",
                                           "reads": len(vals), "rejects": rejv,
                                           "reviewed": 0, "top_well": top,
                                           "value_total": vt if vtmode else 0}
                                    t = txt + json.dumps(row, sort_keys=True, indent=2) + "\n"
                                    if hashlib.sha256(t.encode()).hexdigest() == target:
                                        hits.append((params, bands, lab, stats, pool, tie, vtmode, be, disp, rejv, vals, dbs, drift_end))
print(len(hits))
for h in hits[:40]:
    print(h)

"""Given candidate readings-line lists for a plate, search the plate-row space."""
import json, hashlib, itertools, sys

GR = ("high", "low", "mid", "trace")


def line(d):
    return json.dumps(d, sort_keys=True, separators=(",", ":")) + "\n"


def search(plate, lineslist, target, bes, des, extra_rejects=(), verbose=True):
    hits = []
    for tag, lines in lineslist:
        n = len(lines)
        txt = "".join(line(x) for x in lines)
        wells = [x["well"] for x in lines]
        vals = [x["value"] for x in lines]
        gradesets = []
        g_all = {k: 0 for k in GR}
        for x in lines:
            g_all[x["grade"]] += 1
        gradesets.append(g_all)
        gradesets.append({k: 0 for k in GR})
        pools = {}
        for name, sel in (("none", []), ("all", list(range(n))),
                          ("ok", [i for i, x in enumerate(lines) if x["status"] == "ok"]),
                          ("okrev", [i for i, x in enumerate(lines) if x["status"] in ("ok", "review")]),
                          ("okrevmask", [i for i, x in enumerate(lines) if x["status"] in ("ok", "review", "masked")]),
                          ("nosetup", [i for i, x in enumerate(lines) if x["status"] != "setup"]),
                          ("meas", [i for i, x in enumerate(lines) if x["action"] == "measure"])):
            for tie in ("last", "first"):
                peak, top = 0, None
                for i in sel:
                    if top is None or (vals[i] > peak) or (tie == "last" and vals[i] >= peak):
                        peak, top = vals[i], wells[i]
                pools[(name, tie)] = (peak, top, sum(vals[i] for i in sel))
        for grades in gradesets:
            for be in bes:
                for de in des:
                    for meas in range(0, n + 1):
                        for rev in range(0, n + 1):
                            for rds in {n, len(lines), sum(1 for x in lines if x["action"] == "measure")}:
                                for rej in range(0, n + 1):
                                    for pk, (peak, top, vt) in pools.items():
                                        for disp in ("release", "hold", "quarantine"):
                                            row = {"blank_end": be, "disposition": disp,
                                                   "drift_end": de, "grades": grades,
                                                   "measured": meas, "peak": peak,
                                                   "plate": plate, "reads": rds,
                                                   "rejects": rej, "reviewed": rev,
                                                   "top_well": top, "value_total": vt}
                                            t = txt + json.dumps(row, sort_keys=True, indent=2) + "\n"
                                            if hashlib.sha256(t.encode()).hexdigest() == target:
                                                hits.append((tag, be, de, meas, rev, rds, rej, pk, disp, grades))
    return hits

