"""Knobbed full-run engine. Defaults reproduce the mode-0 chain."""
import json, csv, os, hashlib

MATRICES = ["buffer", "serum", "plasma", "lysate", "saliva", "urine", "media"]
FAMILIES = ["elisa", "pcr", "turbidity", "fluor"]
ROLES = ["technician", "scientist", "trainee", "service"]
GR = ("high", "low", "mid", "trace")

MADJ = {"buffer": ("id", 0), "serum": ("add", -4), "plasma": ("mul", (3, 4)),
        "lysate": ("add", 6), "saliva": ("mul", (1, 2)), "urine": ("snap", 5),
        "media": ("mul", (5, 4))}
PADJ = {"elisa": ("id", 0), "pcr": ("mul", (9, 10)), "turbidity": ("add", 12),
        "fluor": ("mul", (7, 5))}

DEFAULT = dict(
    scope="plate",            # plate | instrument | global
    base_src="blank",         # blank | baseline | none
    gain=1000,
    div="floor",              # floor | ceil | round
    divisor="exposure",       # exposure | replicates | expxrepl | expdivrepl
    matrix_key=0,             # 0 | 1 | -1 | None(skip)
    panel_key=0,
    adj_order="mp",           # mp | pm
    drift_op="sub",           # sub | add | none
    db_report="pre",          # pre | post
    bands=(240, 120, 40),
    band_cmp="ge",
    grade_src="value",        # value | figure
    ladder="std",
    tol=None,
    tol_cmp="gt",
    tol_key="role",           # role | tier
    charge_div=50,
    charge_src="exposure",    # exposure | raw
    tier_mult_on="3",
    tier_mult=2,
    ceiling=90,
    charge_actions=("measure",),
    blank_update="raw",       # raw | value | figure | none
    recal="drift",            # drift | drift_blank | none
    strike_on=("reject",),
    counted=("ok", "review"),
    peak_src="counted",
    well_tie="last",
    quar=3,
    hold=30,
    walk="all",               # all | drop_last | drop_first
    order="seq",              # seq | desc | plate
    plate_tie="first",
    bench_total="all",        # all | released
    top_plate_src="value_total",
)
TOLD = {"technician": 25, "scientist": 40, "trainee": 12, "service": 0}
TIER_TOL = {"1": 25, "2": 12, "3": 0}


def K(**kw):
    d = dict(DEFAULT)
    d["tol"] = dict(TOLD)
    d.update(kw)
    return d


def clamp(x):
    return x if x > 0 else 0


def apply_adj(spec, f):
    k, a = spec
    if k == "id":
        return f
    if k == "add":
        return f + a
    if k == "mul":
        return f * a[0] // a[1]
    if k == "snap":
        return f // a * a
    raise ValueError(k)


def shifted(lst, key, sh):
    return lst[(lst.index(key) + sh) % len(lst)]


def line(d):
    return json.dumps(d, sort_keys=True, separators=(",", ":")) + "\n"


def load(prefix, d="/app/data"):
    p = lambda n: os.path.join(d, prefix + n)
    rd = lambda n: list(csv.DictReader(open(p(n))))
    man = json.load(open(p("manifest.json")))
    ins = {r["instrument"]: r for r in rd("instruments.csv")}
    pan = {r["panel"]: r for r in rd("panels.csv")}
    ops = {r["operator"]: r for r in rd("operators.csv")}
    plt = {r["plate"]: r for r in rd("plates.csv")}
    reads = [json.loads(l) for l in open(p("reads.jsonl")) if l.strip()]
    return man, ins, pan, ops, plt, reads


def run(data, k):
    man, ins, pan, ops, plt, reads = data
    order = sorted(reads, key=lambda r: r["seq"])
    if k["walk"] == "drop_last":
        order = order[:-1]
    elif k["walk"] == "drop_first":
        order = order[1:]
    if k["order"] == "desc":
        order = order[::-1]
    elif k["order"] == "plate":
        order = sorted(order, key=lambda r: (r["plate"], r["seq"]))

    def skey(pname):
        if k["scope"] == "plate":
            return pname
        if k["scope"] == "instrument":
            return plt[pname]["instrument"]
        return "*"

    state = {}
    for pname, prow in plt.items():
        base = int(ins[prow["instrument"]]["baseline"])
        state.setdefault(skey(pname), {"blank": base, "drift": 0})
    strikes = {p: 0 for p in plt}
    readings = []
    for r in order:
        prow = plt[r["plate"]]
        base = int(ins[prow["instrument"]]["baseline"])
        st = state[skey(r["plate"])]
        mat = prow["matrix"]
        fam = pan[prow["panel"]]["family"]
        repl = int(pan[prow["panel"]]["replicates"])
        tier = prow["tier"]
        if k["base_src"] == "blank":
            sub = st["blank"]
        elif k["base_src"] == "baseline":
            sub = base
        else:
            sub = 0
        f = clamp(r["raw"] - sub)
        if k["divisor"] == "exposure":
            dv = r["exposure"]
        elif k["divisor"] == "replicates":
            dv = repl
        elif k["divisor"] == "expxrepl":
            dv = r["exposure"] * repl
        else:
            dv = max(1, r["exposure"] // repl)
        n = f * k["gain"]
        if k["div"] == "floor":
            f = n // dv
        elif k["div"] == "ceil":
            f = -(-n // dv)
        else:
            f = (n + dv // 2) // dv
        f = clamp(f)
        mk = None if k["matrix_key"] is None else shifted(MATRICES, mat, k["matrix_key"])
        pk = None if k["panel_key"] is None else shifted(FAMILIES, fam, k["panel_key"])
        if k["adj_order"] == "mp":
            if mk:
                f = clamp(apply_adj(MADJ[mk], f))
            if pk:
                f = clamp(apply_adj(PADJ[pk], f))
        else:
            if pk:
                f = clamp(apply_adj(PADJ[pk], f))
            if mk:
                f = clamp(apply_adj(MADJ[mk], f))
        fig = f
        db = st["drift"]
        if k["drift_op"] == "sub":
            v = clamp(f - db)
        elif k["drift_op"] == "add":
            v = clamp(f + db)
        else:
            v = clamp(f)
        gv = v if k["grade_src"] == "value" else fig
        h, m, l = k["bands"]
        if k["band_cmp"] == "ge":
            g = "high" if gv >= h else "mid" if gv >= m else "low" if gv >= l else "trace"
        else:
            g = "high" if gv > h else "mid" if gv > m else "low" if gv > l else "trace"
        act = r["action"]
        role = ops[r["operator"]]["role"]
        tol = k["tol"][role] if k["tol_key"] == "role" else TIER_TOL[tier]
        over = db > tol if k["tol_cmp"] == "gt" else db >= tol
        lad = k["ladder"]
        if lad == "std":
            status = ("setup" if act in ("blank", "recal") else "masked" if act == "mask"
                      else "reject" if g == "trace" else "review" if over else "ok")
        elif lad == "mask_first":
            status = ("masked" if act == "mask" else "setup" if act in ("blank", "recal")
                      else "reject" if g == "trace" else "review" if over else "ok")
        elif lad == "review_first":
            status = ("setup" if act in ("blank", "recal") else "masked" if act == "mask"
                      else "review" if over else "reject" if g == "trace" else "ok")
        elif lad == "reject_low":
            status = ("setup" if act in ("blank", "recal") else "masked" if act == "mask"
                      else "reject" if g in ("trace", "low") else "review" if over else "ok")
        elif lad == "recal_measure":
            status = ("setup" if act == "blank" else "masked" if act == "mask"
                      else "reject" if g == "trace" else "review" if over else "ok")
        else:
            raise ValueError(lad)
        # carry update
        newdrift = st["drift"]
        if act == "blank":
            if k["blank_update"] == "raw":
                st["blank"] = r["raw"]
            elif k["blank_update"] == "value":
                st["blank"] = v
            elif k["blank_update"] == "figure":
                st["blank"] = fig
        elif act == "recal":
            if k["recal"] in ("drift", "drift_blank"):
                newdrift = 0
            if k["recal"] == "drift_blank":
                st["blank"] = base
        if act in k["charge_actions"]:
            srcv = r["exposure"] if k["charge_src"] == "exposure" else r["raw"]
            c = srcv // k["charge_div"]
            if k["tier_mult_on"] == "all" or tier == k["tier_mult_on"]:
                c *= k["tier_mult"]
            newdrift = newdrift + c
            if k["ceiling"] is not None and newdrift > k["ceiling"]:
                newdrift = k["ceiling"]
        st["drift"] = newdrift
        readings.append({"action": act, "drift_before": newdrift if k["db_report"] == "post" else db,
                         "grade": g, "operator": r["operator"], "plate": r["plate"],
                         "seq": r["seq"], "status": status, "value": v, "well": r["well"]})
        if status in k["strike_on"]:
            strikes[r["plate"]] += 1
    # rollup
    rows = []
    bymine = {p: [] for p in plt}
    for x in readings:
        bymine[x["plate"]].append(x)
    for name in sorted(plt):
        mine = bymine[name]
        st = state[skey(name)]
        if k["scope"] == "plate":
            blank_end, drift_end = st["blank"], st["drift"]
        else:
            # value carried at the plate's last resolved read
            blank_end, drift_end = st["blank"], st["drift"]
        counted = [x for x in mine if x["status"] in k["counted"]]
        pool = counted if k["peak_src"] == "counted" else mine
        peak, top = 0, None
        for x in pool:
            if top is None or x["value"] > peak or (k["well_tie"] == "last" and x["value"] >= peak):
                peak, top = x["value"], x["well"]
        grades = {g: 0 for g in GR}
        for x in mine:
            grades[x["grade"]] += 1
        rej = strikes[name]
        disp = ("quarantine" if rej >= k["quar"] else "hold" if drift_end > k["hold"] else "release")
        rows.append({"blank_end": blank_end, "disposition": disp, "drift_end": drift_end,
                     "grades": grades, "measured": sum(1 for x in mine if x["action"] == "measure"),
                     "peak": peak, "plate": name, "reads": len(mine), "rejects": rej,
                     "reviewed": sum(1 for x in mine if x["status"] == "review"),
                     "top_well": top, "value_total": sum(x["value"] for x in counted)})
    bg = {g: 0 for g in GR}
    bs = {s: 0 for s in ("masked", "ok", "reject", "review", "setup")}
    for x in readings:
        bg[x["grade"]] += 1
        bs[x["status"]] += 1
    tp, best = None, -1
    for row in rows:
        val = row["value_total"] if k["top_plate_src"] == "value_total" else row["peak"]
        if val > best or (k["plate_tie"] == "last" and val >= best):
            best, tp = val, row["plate"]
    bench = {"by_grade": bg, "by_status": bs, "plates": len(rows),
             "quarantined": sorted(r["plate"] for r in rows if r["disposition"] == "quarantine"),
             "reads": len(readings), "top_plate": tp,
             "value_total": sum(r["value_total"] for r in rows
                                if k["bench_total"] == "all" or r["disposition"] == "release")}
    return readings, {"plates": rows}, bench


def texts(readings, plates, bench):
    rl = "".join(line(r) for r in readings)
    pl = json.dumps(plates, sort_keys=True, indent=2) + "\n"
    bl = json.dumps(bench, sort_keys=True, indent=2) + "\n"
    return rl, pl, bl


def digests(readings, plates, bench):
    rl, pl, bl = texts(readings, plates, bench)
    pd = {}
    for row in plates["plates"]:
        t = "".join(line(r) for r in readings if r["plate"] == row["plate"])
        t += json.dumps(row, sort_keys=True, indent=2) + "\n"
        pd[row["plate"]] = hashlib.sha256(t.encode()).hexdigest()
    return pd, hashlib.sha256((rl + pl + bl).encode()).hexdigest()


def score(data, k):
    man = data[0]
    readings, plates, bench = run(data, k)
    pd, rd = digests(readings, plates, bench)
    ok = [p for p, h in man["plate_digests"].items() if pd.get(p) == h]
    return ok, rd == man["run_digest"]

